import type { Seed } from './roadmap-build';

// "DevOps & cloud" learning path — 120 questions (15 levels × 8), easiest →
// hardest: CI/CD, build pipelines, containers & orchestration, infrastructure
// as code, cloud fundamentals, deploying to AWS/GCP/Vercel, configuration,
// observability, monitoring, secrets and SRE. (ids rm-devops-1 … 120).
export const devopsSeeds: Seed[] = [
  // Level 1 — What is DevOps?
  { q: 'Developers hand builds to an operations team, production feedback arrives days later, and releases are painful. Which change best reflects DevOps?', opts: ['Buy a deployment tool but keep the same hand-off process', 'Give a cross-functional team shared ownership of delivery and production reliability', 'Move all operational decisions to a separate approval board', 'Ask developers to manage servers while operations continues to own releases'], a: 1, e: 'DevOps combines practices, tooling, and shared ownership to shorten the path from code to reliable production service. A tool alone does not remove organizational hand-offs.', tags: ['DevOps', 'basics'], intro: 'The delay between a build and its production feedback is the clue. Ask what sits between the two.' },
  { q: 'A team wants safer releases and faster feedback. Which delivery pattern best supports that goal?', opts: ['Batch six months of work into one carefully planned release', 'Ship small changes frequently with automated checks and quick recovery', 'Run more manual approval meetings before every environment', 'Keep development and operations metrics separate'], a: 1, e: 'Small changes are easier to test, observe, and roll back, and automated checks return feedback in minutes instead of months. Batching six months of work reverses both: the change set is large and the first real feedback arrives at the end, when a failure is hardest to isolate. More approval meetings add delay without adding evidence about whether the change works.', intro: 'Two things are being asked for at once: how large each change is, and how quickly you learn it broke.', tags: ['DevOps', 'goals'] },
  { q: 'Three engineers follow a wiki to build and deploy the same service, but each produces slightly different results. What should be automated first?', opts: ['The incident review, so failed deployments need less discussion', 'The repeatable build, test, and deployment steps', 'The product requirements, so engineers make fewer choices', 'The on-call schedule, so more people can retry the wiki'], a: 1, e: 'Automating repetitive delivery steps makes them consistent and reduces manual error. Human judgment is still needed for product decisions and incident learning.', intro: 'The three engineers all followed the same wiki. Ask which option would remove the difference between their runs.', tags: ['DevOps', 'automation'] },
  { q: 'A service team writes features but cannot see production dashboards or fix its deployment. Which principle is missing?', opts: ['Centralize every production decision in a separate operations queue', '“You build it, you run it”: ownership includes operating the service', 'Keep developers away from incidents to protect feature velocity', 'Measure the team only by how many pull requests it merges'], a: 1, e: 'Shared production ownership gives builders direct feedback about operability and reliability. It does not mean eliminating specialist platform or operations support.', intro: 'Consider who currently sees how the service behaves in production, and whether that information reaches the people changing it.', tags: ['DevOps', 'ownership'] },
  { q: 'Which set of measures best shows both delivery speed and stability?', opts: ['Lines changed, repository count, server count, and meeting time', 'Deployment frequency, change lead time, change fail rate, and failed deployment recovery time', 'Story points, test count, CPU model, and team size', 'Uptime, page views, ad clicks, and cloud spend'], a: 1, e: 'DORA pairs throughput measures (deployment frequency, change lead time, failed deployment recovery time) with instability measures (change fail rate, deployment rework rate), so speed and stability are read together instead of traded off. The current set has five metrics: \'time to restore service\' was renamed failed deployment recovery time and deployment rework rate was added. The other lists count activity or describe hardware, which says nothing about whether delivery is fast or safe.', intro: 'Speed alone can be made to look good by shipping anything, and stability by shipping nothing. Look for the list that would catch both.', tags: ['DevOps', 'dora'] },
  { q: 'An expired certificate causes an outage after one engineer misses a calendar reminder. What should a blameless postmortem examine?', opts: ['Which engineer should receive the incident on their performance review', 'Why renewal depended on one reminder and which system controls can prevent a repeat', 'How to keep the details within the operations team', 'Whether to stop documenting ownership so nobody can be blamed'], a: 1, e: 'A blameless review looks for system conditions—manual renewal, weak alerts, unclear ownership—and turns them into improvements. This encourages candid reporting without removing accountability for follow-up work.', intro: 'Blameless is about what the review looks for, not about hiding what happened. Ask which option would change the outcome if the same mistake happened again.', tags: ['DevOps', 'culture'] },
  { q: 'After several slow deployments, a team measures each stage and removes its largest bottleneck. What practice does this illustrate?', opts: ['Freezing the pipeline once it has passed an audit', 'Continuous improvement driven by delivery feedback', 'Replacing incremental changes with larger release batches', 'Optimizing developer output without measuring production results'], a: 1, e: 'Measuring the pipeline, finding the largest constraint, and removing it is one turn of a continuous improvement loop; the next measurement finds the next constraint. Freezing the pipeline after an audit stops that loop, and counting merged pull requests without looking at production results measures effort rather than delivered improvement.', intro: 'The team measured every stage, then changed only the slowest one. Ask what the next measurement would find.', tags: ['DevOps', 'improvement'] },
  { q: 'Why can releasing ten small changes separately be safer than one large release?', opts: ['Small releases cannot contain defects', 'Each change is easier to verify, diagnose, and roll back', 'Frequent releases remove the need for tests and monitoring', 'A large release always changes more database rows'], a: 1, e: 'Smaller changes reduce the search space when something fails and make rollback or mitigation simpler. They still require testing and observability.', intro: 'Something breaks right after a release. Ask what decides how long it takes to work out which change caused it.', tags: ['DevOps', 'risk'] },

  // Level 2 — Version Control & Git Flow
  { q: 'A team keeps its code on a shared network drive and copies files to the server by hand. What does moving to Git give them that the shared drive cannot?', opts: ['An off-site copy of the files in case a laptop is lost', 'A recorded history of identified changes that automation can trigger on and revert to', 'A guarantee that the code compiles before it is copied to the server', 'A place to run the application\'s tests without a build server'], a: 1, e: 'Git records each change as an identified commit, so a pipeline can start from a push, report exactly which commit produced a build, and return the code to an earlier state. A shared drive holds the current files but no change history, and offers nothing for automation to key off. Git itself neither compiles nor tests; that is the pipeline it triggers.', intro: 'The drive already holds the same files. Ask what the team can still find out about last Tuesday\'s version, and what it cannot.', tags: ['Git', 'basics'] },
  { q: 'A repository requires every change to arrive through a pull request. What does that requirement add, compared with pushing straight to main?', opts: ['A second copy of the branch that is kept on the server', 'A point where review and required checks run before the change lands on main', 'A guarantee that the change will not conflict with other work in progress', 'A record of who deployed the change to production'], a: 1, e: 'A pull request creates a place where another person reads the change and where required status checks run before the merge, so problems are found while the change is still isolated. It does not remove conflicts - those still have to be resolved before merging - and it records nothing about deployment, which happens after the merge.', intro: 'Both routes end with the same commits on main. Ask what happens in between on the pull request route.', tags: ['Git', 'pr'] },
  { q: 'A team adopts trunk-based development. Which working agreement does that commit them to?', opts: ['Each feature gets its own branch, merged once the feature is finished', 'Every developer integrates into main at least daily, so branches live hours rather than weeks', 'Work reaches main only after a release manager approves each commit', 'Main is frozen between releases and changes land on a release branch instead'], a: 1, e: 'Trunk-based development means every developer integrates into the single main branch at least once a day, so branches live hours rather than weeks and each merge is small; unfinished work is hidden behind a flag instead of being held back on a branch. Merging a branch only when the feature is finished is the long-lived-branch model it replaces, and it is exactly the practice that produces large, risky merges.', intro: 'Every option is an agreement about when work is allowed to reach main. Ask which one keeps two developers from drifting apart for long.', tags: ['Git', 'trunk'] },
  { q: 'A feature branch has been open for six weeks while main received two hundred commits. What is the main risk at merge time?', opts: ['The branch\'s commits are rewritten, so their authorship information is lost', 'The combined result has never been built or tested, and the conflicts are six weeks deep', 'Git cannot merge a branch whose base commit is no longer the tip of main', 'Main has to be reset to the branch point before the merge can proceed'], a: 1, e: 'Divergence is what costs: for six weeks nobody built or tested the branch\'s changes together with the two hundred commits on main, so the conflicts and the first integrated test run both arrive on the same day. Git itself merges a diverged branch without complaint - a three-way merge does not require the base commit to still be main\'s tip - so the risk is integration, not a Git limitation. Merging main into the branch regularly converts one large integration into many small ones.', intro: 'Git has no rule against merging a branch whose base is old. Ask what the six weeks cost instead.', tags: ['Git', 'branches'] },
  { q: 'Which branch-protection policy most directly keeps broken or unreviewed changes out of main?', opts: ['Allow direct pushes but ask developers to announce them later', 'Require selected CI checks and review before merge', 'Allow force pushes whenever a local branch is behind', 'Require deployment to finish before any tests may run'], a: 1, e: 'Required checks and reviews turn the merge into an enforced quality gate. A protected branch usually disables direct and force pushes as well.', intro: 'Ask which policy the repository itself enforces, and which only asks people to behave.', tags: ['Git', 'protection'] },
  { q: 'A library at version 2.4.1 removes a function that existing users call. Under semantic versioning, what should the next version be?', opts: ['3.0.0, because the change breaks code that already uses the library', '2.5.0, because the public interface of the library changed', '2.4.2, because no new functionality was added', '2.4.1 with a release note, because removals are documented rather than versioned'], a: 0, e: 'Removing a function breaks existing callers, and semantic versioning increments MAJOR for a backward-incompatible API change, so 2.4.1 becomes 3.0.0 with MINOR and PATCH reset to zero. A MINOR bump is reserved for functionality added in a backward-compatible way and a PATCH bump for backward-compatible fixes; using either here tells consumers the upgrade is safe when it is not.', intro: 'A version number is a promise to the people upgrading. Ask what each of the three numbers promises them.', tags: ['Git', 'semver'] },
  { q: 'A deployment job is changed to check out the tag v2.4.1 instead of the main branch. What does that change?', opts: ['The deployed commit is fixed, so re-running the job later builds the same source', 'The deployment picks up every commit merged to main since the tag was created', 'The tagged commit is removed from the branch history once the deployment finishes', 'The job no longer needs the repository, because a tag is a self-contained archive'], a: 0, e: 'A tag points at one commit and does not move, so checking out v2.4.1 today and in six months produces the same source and the same build. A branch name is a moving pointer that advances with every merge, which is why re-running a deploy from main can ship something other than what was tested. Tagging changes nothing about history and stores no files of its own: the commit stays exactly where it was.', intro: 'A branch name follows new commits. Ask what a tag name does when new commits arrive.', tags: ['Git', 'tags'] },
  { q: 'A half-finished checkout redesign is merged to main behind a flag that is off in production. What has the team gained?', opts: ['The unfinished code is left out of the deployed build until the flag is turned on', 'The branch can be integrated daily while the feature stays invisible to users', 'The redesign can be released to users without being deployed to production', 'The redesign no longer has to be tested before the flag is turned on'], a: 1, e: 'A flag separates deploying from releasing: the code is merged daily and ships with every build, so the branch never diverges, but the path stays unreachable until the flag is turned on. The code is not stripped from the build - it is deployed and inactive, which is why a flagged path still needs tests and eventual cleanup, and why a feature cannot be released to users without first being deployed.', intro: 'Ask what must already be true about the deployed code for the flag to be able to turn the feature on.', tags: ['Git', 'feature-flags'] },

  // Level 3 — CI Basics
  { q: 'Which team is practicing continuous integration?', opts: ['Each developer merges to main at least daily, and every merge triggers an automated build and test run', 'Developers run the full test suite locally before pushing, then merge once the feature is complete', 'A nightly job builds main and emails the results to the team the next morning', 'Every merged change is deployed to production without a manual approval step'], a: 0, e: 'Continuous integration is frequent merging plus an automated build and test of the merged result, so an integration problem surfaces within minutes of the merge that caused it. A nightly build does test the merged result but delays that feedback by up to a day, and local testing never exercises the combination with everyone else\'s work. Automatic deployment describes what happens after the checks; on its own it says nothing about how often changes are integrated or whether anything is tested.', intro: 'Ask how long each team could go without discovering that two changes do not work together.', tags: ['CI', 'basics'] },
  { q: 'A CI pipeline is usually triggered by:', opts: ['A push or pull request to the repository', 'A manual button press by the release manager', 'A production incident alert', 'The app reaching a traffic threshold'], a: 0, e: 'CI runs automatically on repository events (push/PR), giving immediate feedback on each change; scheduled and manual triggers exist but aren\'t the norm.', intro: 'The pipeline has to start on its own, without anyone asking it to. Ask what it would be watching.', tags: ['CI', 'triggers'] },
  { q: 'A typical CI pipeline runs:', opts: ['Install dependencies, lint, build, and test', 'Deploy to production and run smoke tests against it', 'Apply pending migrations to the production database', 'Collect two reviewer approvals before the merge'], a: 0, e: 'A CI run checks the change: it installs dependencies, runs linters and type checks, builds, and executes the test suite, then reports the result on the commit or pull request. Deploying and migrating a production database are delivery steps that follow acceptance of the change, and approvals are given by people in the pull request, not by the runner.', intro: 'Ask which steps a runner can carry out by itself on a change nobody has accepted yet.', tags: ['CI', 'stages'] },
  { q: 'Two developers\' changes each pass the tests on their own branch, but the application breaks once both are on main. Why is CI likely to catch this within minutes?', opts: ['It builds and tests the merged result of main, which neither developer ever built', 'It re-runs each branch\'s own tests with a longer timeout', 'It holds the second merge until the first developer confirms the change', 'It compares the two diffs and reports the lines they both touch'], a: 0, e: 'The failure exists only in the combination, so it appears the first time the merged main is built and tested - which CI does on every merge, minutes after it lands. Re-running each branch\'s own tests would still pass, because each change is fine in isolation, and comparing diffs finds overlapping lines rather than behavior that breaks when two changes meet.', intro: 'Both branches were green before the merge. Ask what that does and does not tell you about main.', tags: ['CI', 'value'] },
  { q: 'Main has been failing CI for two hours and three developers are waiting to merge. What does CI discipline call for?', opts: ['Fix or revert the change that broke main before anything else merges', 'Merge the waiting changes so nobody is blocked, then repair main afterwards', 'Mark the failing test as skipped so the pipeline is green while a fix is written', 'Leave it with the developer who broke it to sort out at the end of the day'], a: 0, e: 'While main is red nobody can tell whether their own change works, and each merge on top adds another suspect to the failure, so the cheapest moment to fix or revert is now. Merging on top spreads the cost across the team, and skipping the test makes the pipeline green while leaving the defect in main - the signal is gone but the problem is not.', intro: 'Ask what each choice leaves the next person to merge, and what main\'s green signal is worth in the meantime.', tags: ['CI', 'discipline'] },
  { q: 'CI configuration is best stored:', opts: ['As code in the repository (e.g. a YAML workflow file)', 'Only in the CI provider\'s web UI, separate from the code', 'In each developer\'s local settings', 'In environment variables on the production server'], a: 0, e: 'Pipeline-as-code (e.g. GitHub Actions YAML) versions the CI config alongside the app, so it\'s reviewable and reproducible — unlike click-configured UI-only pipelines.', intro: 'Ask how the team would find out who changed the pipeline last week, and how they would undo it.', tags: ['CI', 'config'] },
  { q: 'A build passes on a developer\'s laptop and fails on the CI runner. Which property of the runner makes its result the one to trust?', opts: ['It starts from a clean image each run, so nothing depends on state left by earlier work', 'It has more memory and more CPU cores, so it exercises more of the code', 'It runs the suite several times, so intermittent failures are averaged out', 'It installs dependencies from a shared cache, so the versions are always the newest'], a: 0, e: 'A fresh runner has no globally installed tool, no leftover build output and no stale environment variable, so a build that succeeds there depends only on what the repository declares. The laptop\'s success may rest on something installed once and long forgotten, which is why the failing result is the informative one. Machine size and repeated runs do not address that, and a cache restores earlier versions rather than the newest ones.', intro: 'The laptop and the runner ran the same commands from the same repository. Ask what else could have differed.', tags: ['CI', 'reproducible'] },
  { q: 'A pull request pipeline takes fifty minutes. Which consequence most directly harms delivery?', opts: ['Developers batch several changes into one pull request so the wait is paid once', 'The build machines consume more CPU time than a shorter pipeline would', 'The test suite becomes less accurate as its total run time grows', 'The repository ends up with fewer commits recorded per working day'], a: 0, e: 'A long wait pushes developers to batch changes and to move on to something else while it runs, so change sets get larger and the feedback lands after attention has gone, which is the opposite of what small-batch delivery needs. Extra CPU time is a real but minor cost, and pipeline length does not make a suite less accurate; it makes the answer arrive too late to be acted on.', intro: 'One of these is only a bill. Ask which consequence would still hurt if compute cost nothing.', tags: ['CI', 'speed'] },

  // Level 4 — CD & Deployment
  { q: 'A team says it practices continuous delivery. What must be true?', opts: ['Every change that passes the pipeline is released to users automatically', 'Every change that passes the pipeline could be deployed at any time', 'Releases go out on a fixed schedule once a release branch has been stabilized', 'Builds are produced on demand, at the point where a release is planned'], a: 1, e: 'Continuous delivery means every change is automatically built and tested and left in a state where it could be deployed, so releasing becomes a decision rather than a project. Releasing every passing change automatically is continuous deployment - permitted by continuous delivery but not required by it - and stabilizing a release branch on a schedule is the batch model that continuous delivery replaces.', intro: 'Ask what the term still guarantees in a week when the team chooses to release nothing.', tags: ['CD', 'delivery'] },
  { q: 'A team already practices continuous delivery and now moves to continuous deployment. What changes?', opts: ['The release decision is removed, so every change that passes the pipeline reaches production', 'The pipeline gains a build stage, so artifacts stop being produced by hand', 'Tests move out of the pipeline into a nightly job, so merges are never blocked', 'Deployments move into a fixed weekly window agreed with the operations team'], a: 0, e: 'Continuous deployment removes the human release decision: whatever passes the pipeline goes to production, which makes the pipeline\'s checks and the ability to roll back the only remaining safety net. Automated builds and pipeline tests are already part of continuous delivery, so neither is the thing that changes, and moving to a weekly window is a step in the opposite direction.', intro: 'The team already practices continuous delivery. Ask which of these it has already, before asking what is new.', tags: ['CD', 'deployment'] },
  { q: 'A blue-green deployment:', opts: ['Deletes the old version immediately', 'Runs two environments and switches traffic to the new one, enabling instant rollback', 'Deploys without testing', 'Only works locally'], a: 1, e: 'Blue-green keeps the old (blue) and new (green) live; you switch traffic to green and can revert instantly if needed.', tags: ['CD', 'blue-green'] },
  { q: 'A canary release routes five percent of traffic to the new version. What has to be in place for the canary to be worth running?', opts: ['Metrics compared between the two versions and a threshold that triggers an abort', 'A second identical environment sized for the full production load', 'A feature flag that hides the new version from signed-in users', 'A maintenance window during which the remaining traffic is paused'], a: 0, e: 'A canary is a measurement, so the small slice only helps if error rate and latency for the new version are compared with the current one and a threshold decides when to abort. Without that comparison the canary merely exposes some users to an unverified version. A duplicate full-size environment describes blue-green, and no maintenance window is needed because the remaining traffic keeps being served normally.', intro: 'A canary limits how many users are exposed. Ask what else the team has to get out of those five percent.', tags: ['CD', 'canary'] },
  { q: 'A new release causes errors in production. Which response is a rollback?', opts: ['Redeploy the previous release\'s artifact so production runs the last known-good version', 'Merge a fix to main and let the pipeline ship it as the next release', 'Restart the running instances so they come back with clean process state', 'Add instances so the errors are spread across more capacity'], a: 0, e: 'A rollback returns production to the previous release\'s artifact, which has already run successfully, so recovery does not depend on writing correct code under pressure. Merging a fix is rolling forward - sometimes the only option, but slower and unproven - while restarting or scaling leaves the faulty version in place. A rollback is only available while the previous artifact is still retrievable and the release\'s database changes can still be read by the old code.', intro: 'Ask which version production ends up running under each of these four responses.', tags: ['CD', 'rollback'] },
  { q: 'Deploying small changes frequently tends to:', opts: ['Increase risk per release', 'Reduce risk and make failures easier to pinpoint and revert', 'Slow everything', 'Avoid testing'], a: 1, e: 'Smaller deploys change less at once, so they’re lower-risk and easier to debug or roll back.', tags: ['CD', 'small-batches'] },
  { q: 'During a rolling deployment, instances are replaced a few at a time. What does that require of the application?', opts: ['Old and new versions must both work correctly while they run side by side', 'Every instance must be drained of traffic before the first one is replaced', 'The new version\'s artifact must be smaller than the one it replaces', 'The rollout must run inside an agreed maintenance window'], a: 0, e: 'A rolling update replaces instances in batches, so for the length of the rollout both versions handle live requests: the new version has to read what the old one writes and the other way round, which is why API and schema changes have to be backward compatible. Draining every instance first would mean an outage, which is exactly what a rolling update exists to avoid, and artifact size has nothing to do with it.', intro: 'Replacing a few at a time means the others keep serving. Ask which version those others are running.', tags: ['CD', 'rolling'] },
  { q: 'A feature behind a flag starts producing errors an hour after it was turned on. What does the flag make possible?', opts: ['Turning the feature off at runtime, with the rest of the release left in place', 'Rolling the whole release back to the previous artifact in a single step', 'Routing the affected users to the previous version of the service', 'Keeping the errors from being attributed to the current release'], a: 0, e: 'Because deploying and releasing are separate, the feature can be switched off at runtime and everything else in that release keeps running, so recovery does not wait for a build, a pipeline run and a redeploy. Rolling back the artifact is the blunter response and also removes the unrelated changes shipped alongside it, and routing users to a previous version of the service is what a blue-green switch does, not what a flag does.', intro: 'The release also contains unrelated changes that are working fine. Ask what each response would do to those.', tags: ['CD', 'flags'] },

  // Level 5 — Build Pipelines
  { q: 'A build step in a pipeline typically:', opts: ['Compiles/bundles source into a deployable artifact', 'Serves the application to end users', 'Applies database migrations to production', 'Uploads raw source files straight to users\' browsers'], a: 0, e: 'The build transforms source (e.g. TS → JS bundle) into an artifact ready to test and deploy.', intro: 'The step is named for what it does to source code. Ask what state the code is in when it finishes.', tags: ['Pipelines', 'build'] },
  { q: 'A pipeline\'s test stage runs against the output of the build stage rather than building again from source. What must the build stage hand to the test stage?', opts: ['The build artifact - the bundle, package or image the build stage produced', 'The build stage\'s log output, which the test stage reads and parses', 'The dependency cache that the build stage populated', 'The commit SHA, which the test stage uses to check the source out again'], a: 0, e: 'The artifact is the build stage\'s output - a bundle, a package, a container image - and it is the thing later stages test and deploy. A dependency cache does travel between stages, but it only makes a build faster rather than replacing one, and a commit SHA identifies the source, so using it would mean the test stage builds again.', intro: 'The test stage does not build anything. Ask what it therefore has to be given.', tags: ['Pipelines', 'artifacts'] },
  { q: 'In a pipeline, the deploy job must not start unless the test job has succeeded. How is that guaranteed?', opts: ['By declaring that deploy depends on test, so the runner orders them and skips deploy if test fails', 'By listing deploy after test in the file, because jobs run in the order they appear', 'By giving deploy a delay long enough for test to finish first', 'By starting both and cancelling deploy if test later reports a failure'], a: 0, e: 'Jobs run in parallel unless a dependency is declared - in GitHub Actions with needs, which names the jobs that must complete successfully before this job runs - and the runner then both orders them and skips the dependent job when the dependency fails. File order changes nothing, a delay is a race rather than a guarantee, and cancelling deploy after it has started means part of the deployment may already have happened.', intro: 'Ask what each of these would do on a run where the test job fails after ten minutes.', tags: ['Pipelines', 'stages'] },
  { q: 'A pipeline stops at the first failing step instead of running the remaining steps. What is the trade-off?', opts: ['Feedback arrives sooner, but only the first failure is reported, not every failure in the run', 'Feedback arrives sooner, and the skipped steps are retried automatically after the fix', 'The run costs more, but every failure in the pipeline is reported at once', 'Nothing is given up, because a failing step never affects the steps after it'], a: 0, e: 'Failing fast returns an answer sooner and avoids spending runner time on stages that cannot succeed, but the run reports only the first failure, so a second, unrelated problem stays hidden until the next run. That is why independent checks - lint, unit tests, a version matrix - are often allowed to finish so every failure is visible at once; a matrix in GitHub Actions cancels its remaining jobs by default and has to be told not to. A failing step usually does affect what follows: a failed build leaves the test stage nothing to run.', intro: 'Picture a run where the lint step and a unit test are both broken. Ask what the report ends up showing.', tags: ['Pipelines', 'fail-fast'] },
  { q: 'A pipeline builds the application in the staging job and builds it again in the production job, from the same commit. What risk does that introduce?', opts: ['The two builds can differ, so what was tested in staging is not what production runs', 'The commit\'s SHA changes when it is built twice, so the release cannot be traced', 'Staging and production must then run the same operating system', 'The pipeline can no longer record which commit produced the release'], a: 0, e: 'A build depends on more than the commit - dependency resolution, base image tags, toolchain versions, build-time environment - so building twice can produce two different artifacts, and the one that passed staging is not the one serving users. Building once and promoting that same artifact through each environment closes the gap. Rebuilding changes neither the commit SHA nor the pipeline\'s record of it; the difference is in the output, not in the history.', intro: 'Ask what a build depends on besides the commit it starts from.', tags: ['Pipelines', 'promotion'] },
  { q: 'A pipeline caches the installed dependency directory under a key that never changes. What is the risk?', opts: ['A build can restore a dependency tree that no longer matches the lockfile', 'The cache is ignored, because a key has to contain a hash to be usable', 'The first build after the cache expires fails instead of reinstalling', 'Each job in the run writes its own separate copy of the cache'], a: 0, e: 'A cache key ties the cached content to the inputs that produced it, which is why dependency caches are keyed on a hash of the lockfile: change the lockfile and the key changes, so the pipeline installs fresh. A key that never changes keeps restoring the old tree after the lockfile has moved on, and the build then passes CI using versions nobody declared. A cache miss is not a failure - the step simply installs and repopulates the cache.', intro: 'Suppose someone upgrades a dependency tomorrow. Ask what this pipeline would install on the next run.', tags: ['Pipelines', 'cache'] },
  { q: 'A pipeline should be:', opts: ['Manual and undocumented', 'Defined as code, versioned, and reproducible', 'Different every run', 'Stored only locally'], a: 1, e: 'Pipeline-as-code makes the delivery process reviewable, reproducible, and consistent across runs.', tags: ['Pipelines', 'as-code'] },
  { q: 'Running tests as a pipeline stage before deploy ensures:', opts: ['Faster bugs in prod', 'Only verified artifacts get promoted/deployed', 'No need for tests', 'Random deploys'], a: 1, e: 'Gating deploys on tests prevents shipping artifacts that fail verification.', tags: ['Pipelines', 'gating'] },

  // Level 6 — Containers & Docker
  { q: 'A container image is built for a Node application. What does the image contain?', opts: ['The application, its Node runtime and its installed dependencies', 'The application and its dependencies; the Node runtime comes from the host at start-up', 'The application source only; dependencies are installed when the container starts', 'The application, its dependencies and its own copy of the host\'s kernel'], a: 0, e: 'An image carries the application together with its runtime and its installed dependencies, so the host needs only a container runtime - no Node installation and no install step at start-up. That self-containment is what makes the same image behave the same on a laptop and on a server. What the image does not carry is a kernel: containers use the host\'s.', intro: 'Ask what still has to be installed on the host machine before this image can run.', tags: ['Containers', 'basics'] },
  { q: 'A service runs on a developer\'s laptop but crashes in CI, which has a different Node version installed. How does containerizing the service help?', opts: ['The Node version is fixed in the image, so both machines run the same runtime', 'The container detects the host\'s Node version and adapts the application to it', 'The container installs the newest Node version at start-up in both places', 'The container isolates the crash, so CI reports the run as passing'], a: 0, e: 'The runtime version is baked into the image, so the laptop and the CI runner execute the same Node build and the version difference stops mattering. Containers neither detect the host\'s versions nor upgrade themselves at start-up - pinning is what produces the consistency. What an image cannot equalize is what lives outside it: different data, different environment variables and a different host architecture can still make behavior diverge.', intro: 'The two machines differ in exactly one thing. Ask what the image does with that thing.', tags: ['Containers', 'consistency'] },
  { q: 'Three containers are started from the same image. One of them writes a file into its filesystem. What is true?', opts: ['Each container has its own writable layer, so the file is invisible to the other two', 'The three share one writable layer, so the file appears in all of them', 'The image is updated with the file, so containers started later will have it', 'The write fails, because a container\'s filesystem is read-only'], a: 0, e: 'An image is a read-only stack of layers; starting a container adds a writable layer belonging to that container alone, so three containers begin identical and then diverge independently. The image is never modified by a running container, which is why anything written this way disappears when the container is replaced unless it was written to a volume.', intro: 'The image itself is read-only. Ask where a container\'s writes can go instead.', tags: ['Containers', 'image'] },
  { q: 'Why does a container start in under a second while a virtual machine running the same application takes tens of seconds?', opts: ['The container starts a process on the host\'s running kernel; the VM boots its own kernel and OS first', 'The container image is compressed, so less data has to be read from disk', 'The container skips the application\'s own start-up work that a VM performs', 'The container runs without any operating system, so there is nothing to boot'], a: 0, e: 'A container is an isolated process on the host\'s kernel, so starting it means setting up namespaces and running the entrypoint; a virtual machine has to boot a kernel and an operating system before the application starts, and that is where the seconds go. The image still contains operating system user space - libraries, a shell, sometimes a package manager - so \'no operating system\' is wrong; what it leaves out is the kernel. Compression affects how long a pull takes, not start-up.', intro: 'Ask what a virtual machine has to finish before the application\'s first line runs, that a container never does.', tags: ['Containers', 'vs-vm'] },
  { q: 'A team edits its Dockerfile. When does the change take effect?', opts: ['At the next image build; existing images and running containers are unaffected', 'Immediately, because running containers read the Dockerfile while they run', 'At the next container restart, when the Dockerfile is read again', 'When the image is pushed to the registry, which applies the new instructions'], a: 0, e: 'A Dockerfile is a build-time recipe: a build runs its instructions once to produce an image, and nothing consults the file afterwards. Running containers were started from an image that already exists, so they keep running the old one until a new image is built and they are replaced. Pushing only uploads an image that has already been built.', intro: 'Ask at which single point the instructions in the file are actually executed.', tags: ['Containers', 'dockerfile'] },
  { q: 'A Dockerfile copies the whole project directory and then runs the dependency install. Why does every rebuild reinstall the dependencies, even when only one source file changed?', opts: ['The COPY step is invalidated, and every instruction after it has to run again', 'Dependency installs are never cached, because they download from the network', 'Build instructions are evaluated in reverse order, so the install runs first', 'Layers are merged at the end of the build, so caching applies only to the base image'], a: 0, e: 'The build cache is invalidated at the first instruction whose inputs changed, and everything after that point is rebuilt: copying the whole project before installing means any source edit invalidates the COPY and forces the install again. Copying only the manifest and lockfile, installing, and then copying the rest keeps the install cached across source edits. Instructions are evaluated in file order, and reaching the network does not by itself disable caching.', intro: 'The install instruction itself did not change. Ask what happened to the instruction in front of it.', tags: ['Containers', 'layers'] },
  { q: 'A CI job builds a container image, and a machine elsewhere has to run it. What does the registry do in that flow?', opts: ['CI pushes the built image to it, and the deploy target pulls that same image', 'It stores the Dockerfile so the deploy target can build an identical image itself', 'It rebuilds the image on the deploy target whenever a new version is pushed', 'It runs the image and exposes the running container to the deploy target'], a: 0, e: 'A registry stores built images: CI pushes the image it produced and the deploy target pulls exactly that image, so the bytes that were tested are the bytes that run. It holds images rather than Dockerfiles, and it neither builds nor runs anything - rebuilding on the target would reintroduce the build differences that shipping one artifact is meant to remove.', intro: 'The image was built once, on the CI machine. Ask how a second machine ends up with that same image.', tags: ['Containers', 'registry'] },
  { q: 'A Dockerfile compiles the application in a stage based on a full SDK image, then copies the compiled output into a stage based on a minimal runtime image. What does the final image contain?', opts: ['The runtime base plus the copied output; the compiler and build dependencies are absent', 'Both stages\' layers, because every stage contributes to the finished image', 'Only the files named in the last COPY, with no base image underneath', 'The SDK stage\'s layers, because the final stage was built on top of them'], a: 0, e: 'Only the last stage becomes the image: it starts from its own base and receives whatever earlier stages explicitly copy in, so the compiler, headers and build caches stay behind. That is what keeps the image small, and it also removes build tooling from what runs in production, which shrinks the attack surface. The earlier stages are still executed during the build - they just do not end up in the result.', intro: 'Ask which stage the finished image is built from, and what crosses over from the other one.', tags: ['Containers', 'multi-stage'] },

  // Level 7 — Container Orchestration (Kubernetes)
  { q: 'A service runs as twelve containers spread over four machines, and one machine fails. What does an orchestrator do that a plain container runtime does not?', opts: ['Notices the containers are gone and schedules replacements on the remaining machines', 'Repairs and restarts the failed machine so its containers come back on it', 'Holds incoming requests in a queue until the failed machine returns', 'Moves the failed machine\'s containers to another machine with their local files intact'], a: 0, e: 'An orchestrator tracks how many replicas should be running and replaces the ones that disappear, scheduling them onto healthy machines without anyone being paged. It does not repair hardware, and it does not carry a container\'s local filesystem across - anything that has to survive belongs in a volume or an external store. Requests are not queued either; the load balancer simply stops sending traffic to endpoints that no longer exist.', intro: 'Ask what the orchestrator was told to keep true about this service, and what stopped being true when the machine died.', tags: ['Kubernetes', 'basics'] },
  { q: 'A web server container and a log-shipping sidecar have to reach each other on localhost and read the same local volume. How should they be deployed?', opts: ['As two containers in one Pod', 'As two Pods in one Deployment', 'As two Deployments in one Namespace', 'As two containers on one Node'], a: 0, e: 'Containers in one Pod are co-located and run in a shared context: they share network and storage resources, so they reach each other on localhost and can mount the same volume - exactly what a sidecar needs. Separate Pods get separate addresses and cannot share a local volume, and a Deployment or a Namespace groups Pods rather than co-locating containers. Being on the same Node is not enough either: co-location on a node is a scheduling outcome, not a shared network and storage context.', intro: 'Ask which of these groupings Kubernetes schedules as a single unit, and which only organize objects.', tags: ['Kubernetes', 'pod'] },
  { q: 'A Deployment declares three replicas. An operator deletes one of its Pods by hand. What happens?', opts: ['A replacement Pod is created and the count returns to three', 'The workload stays at two replicas until someone scales it back up', 'The deleted Pod is recreated with the same name and the same IP address', 'All three Pods are recreated, because the live state no longer matches the Deployment'], a: 0, e: 'A Deployment owns a ReplicaSet whose job is to keep the declared number of Pods running, so a deleted Pod is replaced within seconds. The replacement is a new Pod with a new name and a new IP address, which is why clients address a Service rather than a Pod, and the two surviving Pods are left alone - only the missing replica is recreated.', intro: 'The declared replica count did not change. Ask what the controller does once the cluster stops matching it.', tags: ['Kubernetes', 'deployment'] },
  { q: 'Pods are replaced on every deploy and each replacement gets a new IP address. How do other workloads keep reaching this one?', opts: ['Through a Service, whose name and address stay fixed while its endpoints change', 'Through the Pod\'s IP, which Kubernetes reassigns to the replacement Pod', 'Through the Node\'s IP, which is stable for as long as the node exists', 'Through the Deployment\'s name, which resolves to whichever Pod is healthy'], a: 0, e: 'A Service is a stable name and address in front of a changing set of Pods: as Pods come and go its endpoint list is updated, and traffic is load-balanced across the ones that are ready. A Pod\'s IP belongs to that Pod and is not handed to its replacement, a Node\'s IP addresses a machine rather than a workload, and a Deployment is a controller with no network identity - nothing resolves to it.', intro: 'Pods come and go. Ask what has to keep an up-to-date list of them, and what callers use instead.', tags: ['Kubernetes', 'service'] },
  { q: 'A Deployment\'s manifest declares five replicas. Someone scales the workload to eight with a one-off command and does not change the manifest. What happens when the manifest is applied again?', opts: ['The count returns to five, because the manifest is the declared state', 'The count stays at eight, because the more recent instruction wins', 'The count becomes thirteen, because the two instructions are combined', 'The apply is rejected, because live state no longer matches the manifest'], a: 0, e: 'Kubernetes stores the declared state and continuously drives the cluster toward it, so re-applying the manifest sets the count back to five and the one-off change is lost. That is why imperative commands belong to experiments and the manifest in version control is the source of truth. An apply is not rejected for disagreeing with live state - resolving that disagreement is exactly what it does.', intro: 'Ask what apply writes into the cluster, and what that does to a field someone changed by hand.', tags: ['Kubernetes', 'declarative'] },
  { q: 'CPU use across a Deployment\'s Pods rises above the target and the HorizontalPodAutoscaler reacts. What does it change?', opts: ['The Deployment\'s replica count, so the load is spread across more Pods', 'The CPU limit on each existing Pod, so each one can do more work', 'The Pods\' scheduling priority, so they receive more of each node\'s time', 'The number of nodes in the cluster, so there is more capacity to schedule onto'], a: 0, e: 'An HPA updates the workload resource\'s replica count, so demand is met by adding Pods; the Pods themselves are untouched. Raising each Pod\'s CPU limit is vertical scaling and is a different controller\'s job, and adding nodes is the cluster autoscaler\'s - often needed alongside an HPA, since the new Pods still have to fit somewhere.', intro: '\'Horizontal\' names the direction. Ask whether that means more of the same thing, or more room for each one.', tags: ['Kubernetes', 'hpa'] },
  { q: 'A Pod\'s application takes forty seconds to warm its cache before it can serve requests. Which probe keeps traffic away until then?', opts: ['A readiness probe, which holds the Pod out of its Service\'s endpoints until it passes', 'A liveness probe, which restarts the container until it starts responding', 'A startup probe, which delays the container\'s process until the cache is warm', 'Either probe, because both decide whether a Pod receives traffic'], a: 0, e: 'A readiness probe decides whether a Pod appears in its Service\'s endpoint list, so traffic is withheld through the warm-up and resumes the moment it passes. A liveness probe answers a different question - whether to restart the container - and pointing it at a slow start-up produces a restart loop. A startup probe does not delay the process; it exists to keep the liveness probe quiet while a slow application starts.', intro: 'Ask what each of these probes does when it fails, and which of those actions this container needs during warm-up.', tags: ['Kubernetes', 'probes'] },
  { q: 'A three-person team runs one web app and one background worker on a managed platform. What is the strongest argument against moving to Kubernetes?', opts: ['The cluster becomes another system to operate, upgrade and secure, for capability they do not need yet', 'Kubernetes cannot run a workload as small as two services', 'Kubernetes requires the application to be split into microservices first', 'Kubernetes only runs containers built from a specific set of base images'], a: 0, e: 'Adopting Kubernetes adds a platform that has to be operated, upgraded and secured, together with manifests, networking and access control to learn - cost that is repaid only when scale or multi-team coordination demands it. Kubernetes runs small workloads perfectly well and imposes neither a microservice architecture nor particular base images; the argument against it here is operational cost, not capability.', intro: 'This team\'s platform is operated by somebody else today. Ask what that would change about their week.', tags: ['Kubernetes', 'tradeoffs'] },

  // Level 8 — Infrastructure as Code
  { q: 'A team needs a second staging environment identical to the one they already run. What does having their infrastructure as code give them?', opts: ['The same definitions can be applied again with different parameters to build it', 'The running virtual machines can be cloned, which copies the environment exactly', 'The cloud provider keeps a template of the first environment that can be reused', 'The application\'s configuration file can point at both environments at the same time'], a: 0, e: 'Because the environment is described in code, building another one means applying the same definitions with different parameters, and the result is identical every time rather than identical as far as anyone remembers. Cloning running machines copies whatever drift they have accumulated, and a provider keeps no record of how a hand-built environment was assembled.', intro: 'Ask what a team can do with a written definition that they cannot do with an environment somebody clicked together.', tags: ['IaC', 'basics'] },
  { q: 'A production firewall rule is changed through the team\'s infrastructure code instead of the cloud console. What does that add?', opts: ['The change arrives as a reviewable diff and its history is recorded with the code', 'The change takes effect faster than the same edit made in the console', 'The change can be applied without credentials for the cloud account', 'The change cannot cause an outage, because the tool validates the result first'], a: 0, e: 'Routing infrastructure changes through code means each one is proposed as a diff, reviewed, recorded next to the application\'s history, and revertible the same way, so a firewall rule gets the same scrutiny as a code change. It is not faster than clicking, it still needs credentials to apply, and validation catches malformed configuration rather than a rule that is well-formed and wrong.', intro: 'Ask what record a console edit leaves behind, and who else would ever see it.', tags: ['IaC', 'benefits'] },
  { q: 'A Terraform configuration declares three servers. Two of them already exist. What does applying the configuration do?', opts: ['Creates the missing one and leaves the two existing servers alone', 'Creates three more servers, leaving five in total', 'Destroys the two existing servers and creates all three fresh', 'Fails, because the live infrastructure does not match the configuration'], a: 0, e: 'Terraform configurations describe the end state of the infrastructure, so an apply compares that description with its recorded state and makes only the changes needed - here, creating the one missing server. An imperative script would run its create commands regardless and leave five. A mismatch is not an error either; resolving it is what an apply is for.', intro: 'Ask what the tool would have to know about the two servers that already exist before it does anything.', tags: ['IaC', 'terraform'] },
  { q: 'During an incident someone widens a security group in the cloud console. The infrastructure configuration is not updated. What happens at the next apply?', opts: ['The manual change is reverted, because the configuration is still the declared state', 'The manual change is read back and adopted into the configuration automatically', 'The apply is blocked until somebody reconciles the difference by hand', 'Nothing changes, because the tool only manages resources it created in that run'], a: 0, e: 'Drift is the gap between a live resource and its definition, and an apply closes that gap in the direction of the definition, so the emergency change disappears unless someone writes it into the configuration. That is the mechanism behind fixes that quietly vanish days later, and it is why console changes made during an incident have to be back-ported. The tool manages every resource in its state, not only the ones created by the current run.', intro: 'Ask what would have had to happen for the emergency change to survive the next apply.', tags: ['IaC', 'drift'] },
  { q: 'Idempotent IaC means applying the same config:', opts: ['Each run creates another copy of the declared resources', 'Each run leaves the declared state in place, changing only what differs', 'Only the first run succeeds; later runs are rejected as duplicates', 'Every run needs a manual approval step before it can proceed'], a: 1, e: 'Idempotent means the outcome depends on the declared state, not on how many times you apply it: the first run creates what is missing and later runs report no changes. Creating another copy each time is the non-idempotent behavior of an imperative script that only knows how to create. Idempotency is what makes it safe to re-run a pipeline after a partial failure.', intro: 'Ask what the second and third apply of an unchanged configuration should do.', tags: ['IaC', 'idempotent'] },
  { q: 'Immutable infrastructure favors:', opts: ['Patching each running server in place for as long as it lives', 'Building a new image and replacing running instances with it', 'Editing servers over SSH and recording the change in a ticket', 'Freezing servers so nothing about them is ever updated'], a: 1, e: 'Immutable infrastructure changes the image, not the running box: you build a new version and replace instances, so every server matches an artifact you can rebuild. Frozen forever is the common misreading - the fleet does change, it changes by replacement. In-place patching is what lets each server drift into a state nobody can reproduce.', intro: 'Think about what happens to the running instance when a package needs a new version.', tags: ['IaC', 'immutable'] },
  { q: 'Storing IaC in version control gives you:', opts: ['No history', 'Review, history, and rollback for infrastructure changes', 'Slower deploys only', 'Less reproducibility'], a: 1, e: 'Versioned IaC brings code-style review, audit history, and rollback to infrastructure changes.', tags: ['IaC', 'vcs'] },
  { q: 'A team manages its infrastructure with Terraform. Which pipeline arrangement matches how IaC is normally delivered?', opts: ['Engineers apply from their laptops and commit the result afterward', 'The pipeline runs a plan on the pull request and applies it on merge', 'The pipeline applies every push, with no review of the planned changes', 'Changes are made in the cloud console and the code is regenerated nightly'], a: 1, e: 'The flow mirrors code review: the pull request runs a plan so the diff against real resources is visible, and the merge runs the apply. Applying on every push skips the one step that makes an infrastructure change reviewable. Laptop applies leave the state file and the repository disagreeing about what is actually deployed.', intro: 'Compare each arrangement with the way an application code change in the same team reaches production.', tags: ['IaC', 'cicd'] },

  // Level 9 — Cloud Fundamentals
  { q: 'Cloud computing provides:', opts: ['Hardware you buy and rack in space rented from a data center', 'Computing resources you request on demand and pay for by usage', 'A fixed set of servers leased at a flat price for a year at a time', 'Any application whose data happens to be stored on the internet'], a: 1, e: 'Cloud computing means capacity is provisioned through an API on request and billed by what you consume, so it can be added and removed in minutes. A year-long lease at a flat price is traditional hosting: you pay for the machine whether or not it is busy. Colocation is renting rack space for hardware you still own and operate.', intro: 'Consider what happens to cost and capacity when traffic doubles for one afternoon and then drops back.', tags: ['Cloud', 'basics'] },
  { q: 'IaaS, PaaS, and SaaS differ mainly in:', opts: ['How much of the stack the provider operates for you', 'Which programming languages the workload may be written in', 'Whether the workload runs in one region or several', 'Whether the provider bills monthly or by the second'], a: 0, e: 'The three are points on one axis of responsibility: with IaaS you get machines and run everything above them, with PaaS the provider runs the OS and runtime and you supply the application, and with SaaS you supply only data and configuration. Language, region, and billing granularity all vary inside each model, so none of them separates the three.', intro: 'For each option, ask whether two products in the same model could still differ on it.', tags: ['Cloud', 'service-models'] },
  { q: 'Serverless (e.g. Lambda, Vercel Functions) means:', opts: ['There are no servers involved anywhere in the request path', 'You deploy functions and the provider runs and scales them per request', 'You rent a virtual machine and keep it running to host your functions', 'You manage the operating system but not the application runtime'], a: 1, e: 'Serverless means you neither provision nor operate the machines: you ship a function and the platform starts as many instances as the request rate needs, then stops them. Servers still exist - the name describes your responsibility, not the hardware. Renting a VM and keeping it running is the opposite trade: you pay for idle capacity and scale it yourself.', intro: 'Ask who decides how many instances exist while your traffic rises and falls.', tags: ['Cloud', 'serverless'] },
  { q: 'Cloud "elasticity" refers to:', opts: ['Capacity is fixed at the size reserved up front', 'Capacity grows and shrinks automatically as demand changes', 'Capacity grows automatically but must be reduced by hand', 'Capacity is resized by opening a ticket with the provider'], a: 1, e: 'Elasticity works in both directions: the platform adds instances when load rises and removes them when it falls, so spend roughly follows use. Scaling up only is the common half-measure - it protects availability but leaves the bill at peak size all night. Fixed reserved capacity is the pre-cloud model the term was coined against.', intro: 'Check what each option says about the hours after the traffic spike ends.', tags: ['Cloud', 'elasticity'] },
  { q: 'An app must store user-uploaded images and nightly database dumps. Why is object storage such as S3 the right home for them?', opts: ['It stores large files cheaply and serves them by key over HTTP', 'It indexes the files so they can be joined against relational tables', 'It gives the files transactional updates that roll back on failure', 'It mounts as a POSIX filesystem so processes can seek inside files'], a: 0, e: 'Object storage keeps opaque blobs addressed by key, durably replicated and priced for bulk, which is exactly the shape of images and backups. It has no join engine, no transactions spanning objects, and it is not a POSIX filesystem: you replace an object rather than seeking into it. Those needs belong to a database or a block/file volume.', intro: 'Ask what the store would have to know about a file\'s contents to do what each option describes.', tags: ['Cloud', 'storage'] },
  { q: 'Your service runs in a single availability zone of one region. What do you gain by spreading it across zones?', opts: ['Lower cost, since capacity in a second zone is billed at a discount', 'Survival of a failure confined to one zone\'s power or network', 'Lower latency for users everywhere, since zones are spread worldwide', 'Automatic backups of the disks attached to your instances'], a: 1, e: 'Availability zones are separate failure domains inside one region - separate power, cooling and network - so a workload spread across two of them survives losing one. They are close enough that latency between them is small, which is why they do not help a user on another continent; that is what a second region is for. Zone placement changes neither billing rates nor backups.', intro: 'Compare what a second zone protects you from with what a second region would give you.', tags: ['Cloud', 'regions'] },
  { q: 'Under pay-as-you-go pricing, what is a cloud bill actually computed from?', opts: ['Compute time, stored bytes, requests served, and outbound data transfer', 'Compute time only; storage and network are included in the rate', 'The peak capacity you reserved, whether or not you used it', 'A flat monthly rate per project, with usage counted only above a cap'], a: 0, e: 'Usage billing meters several dimensions at once: how long compute ran, how many bytes are stored, how many requests were served, and how much data left the provider\'s network. Outbound transfer is the one teams forget, which is how a bill grows while the instance count stays flat. Reserved capacity is a different model - you pay for the reservation whether the workload uses it or not.', intro: 'Test each option against a service that stores a terabyte and serves it constantly but runs almost no compute.', tags: ['Cloud', 'cost'] },
  { q: 'A staging environment costs almost as much as production. Which cause is most likely?', opts: ['Instances sized for peak production load that run around the clock', 'Deploying to it more often than production is deployed to', 'Keeping a separate database schema from the production one', 'Running the same test suite that the production pipeline runs'], a: 0, e: 'Charges accrue for as long as a resource exists, so an over-sized instance costs the same at 3 a.m. as at peak, and a staging environment sized like production bills like production. Extra deploys, a second schema and a test run consume very little by comparison. The fixes are right-sizing and shutting non-production environments down when nobody is using them.', intro: 'Ask how many hours a day each cause is incurring charges, and at what size.', tags: ['Cloud', 'finops'] },

  // Level 10 — Deploying to AWS/GCP/Vercel
  { q: 'Which workload is a frontend platform such as Vercel or Netlify designed to host?', opts: ['A statically built site with serverless API routes beside it', 'A Postgres cluster with tuned storage and automatic failover', 'A worker that keeps a queue connection open between jobs', 'A Kubernetes control plane shared by several internal teams'], a: 0, e: 'These platforms build the repository into static assets served from a CDN and run request handlers as short-lived serverless functions, which is exactly a site plus API routes. A database, a worker holding a connection open, and a cluster control plane all need processes that outlive a request, so they belong on managed data services or your own compute.', intro: 'For each workload, ask what has to be running between two requests.', tags: ['Deploy', 'paas'] },
  { q: 'How is a static site or SPA normally deployed?', opts: ['The build output is uploaded once and served from CDN edge caches', 'A Node process renders each page when the request arrives', 'The source files are copied to a server and compiled per request', 'An origin server runs a separate copy of the app per connected user'], a: 0, e: 'A static build produces files that are identical for every visitor, so the deploy is an upload: assets go to a CDN and are served from the edge nearest the user. Rendering each request is what server-side rendering does, and it needs a running process - the thing a static deploy removes. Compiling per request would repeat work whose result never changes.', intro: 'Ask what the build produces, and whether any of it changes between one visitor and the next.', tags: ['Deploy', 'static'] },
  { q: 'The first request to an idle serverless function is noticeably slower than the ones after it. What is happening?', opts: ['A new execution environment is being created and initialized', 'The platform is retrying the request after an internal error', 'A CDN is revalidating a stale cached response for that path', 'The function\'s memory limit is being raised to fit the payload'], a: 0, e: 'A cold start is the time the platform spends downloading the code, starting the runtime, and running your module-level initialization before the handler is called; a warm request reuses an environment that is already set up. AWS puts a typical cold start between under 100 ms and over a second, on well under 1% of invocations. Moving heavy work out of module scope, or paying for provisioned concurrency, is how teams shrink it.', intro: 'Ask what the platform keeps running while a function sits idle with no traffic.', tags: ['Deploy', 'cold-start'] },
  { q: 'Environment variables are commonly used in deploys to:', opts: ['Store source code', 'Provide per-environment config and secrets without hardcoding them', 'Replace the database', 'Compile code'], a: 1, e: 'Env vars inject configuration/secrets per environment, keeping them out of the codebase.', tags: ['Deploy', 'env'] },
  { q: 'What does moving to a managed database service such as RDS or Cloud SQL take off your plate?', opts: ['Backups, minor-version patching, and failover to a standby', 'Schema design, indexing, and slow-query investigation', 'Deciding how much storage and CPU the database needs', 'Access control and the rules for who may read which data'], a: 0, e: 'A managed service operates the engine: scheduled backups, minor-version patches in a maintenance window, and failover to a standby. Everything about how you use the database stays yours - schema, indexes, slow queries, instance sizing, and who may connect. Assuming otherwise is how teams end up with a thoroughly backed-up database that cannot serve its traffic.', intro: 'For each option, ask whether the provider could do it without knowing anything about your application.', tags: ['Deploy', 'managed-db'] },
  { q: 'A common deploy pattern is to run CI/CD that:', opts: ['Manually copies files over FTP', 'Builds, tests, then deploys the artifact to the cloud automatically', 'Edits production by hand', 'Skips builds'], a: 1, e: 'Automated pipelines build/test and then deploy artifacts to the target platform, removing manual error-prone steps.', tags: ['Deploy', 'cicd'] },
  { q: 'A platform builds every pull request to its own temporary URL. What does that add to code review?', opts: ['Reviewers can exercise the change in a running copy before merging', 'The change no longer has to pass the test suite to be merged', 'The pull request merges automatically once the build succeeds', 'Production traffic is split between the old and the new version'], a: 0, e: 'A preview deployment gives each pull request a real running instance, so a reviewer can click through the change instead of imagining it from the diff - layout, copy and behavior included. It does not replace CI and it does not merge anything. Splitting live traffic between versions is a canary release, which happens after the merge, on production.', intro: 'A diff shows what changed in the source. Ask what a reviewer still cannot judge from it.', tags: ['Deploy', 'previews'] },
  { q: 'One instance behind a load balancer starts failing its health check. What does the platform do with it?', opts: ['Takes it out of rotation, and replaces it if it stays unhealthy', 'Keeps routing to it but marks its responses as degraded', 'Restarts every instance in the group to clear the fault', 'Blocks the next deployment until the endpoint recovers'], a: 0, e: 'A failing check takes the instance out of the load balancer\'s rotation immediately, and the autoscaling group or scheduler terminates and replaces it if it does not recover. Traffic is never deliberately sent to an instance known to be failing. The healthy instances are left alone - restarting the whole group would turn one bad instance into an outage.', intro: 'Ask what happens to the requests aimed at that instance, and then what happens to the instance.', tags: ['Deploy', 'health'] },

  // Level 11 — Environments & Config
  { q: 'A change moves from a developer\'s machine to users. Which sequence of environments is the common default?', opts: ['Development, then a shared staging environment, then production', 'Development, then production, with staging used only after incidents', 'A single shared environment that everyone develops and releases from', 'Development and production, with tests run against production data'], a: 0, e: 'Development is where changes are written, staging is a production-like environment where they are verified against realistic config and data, and production serves users. Skipping staging means the first production-like run is the one users get. Testing against production data, or releasing out of the environment you develop in, removes exactly the safety the ladder exists to provide.', intro: 'Ask what each sequence would catch before release, and what it would catch only after.', tags: ['Config', 'environments'] },
  { q: 'Why does keeping config out of the build let a team promote one artifact through its environments?', opts: ['The same image runs anywhere; only the injected values change', 'Each environment gets its own build with its values compiled in', 'Config can then be committed alongside the code that reads it', 'The build gets smaller, so it uploads to each environment faster'], a: 0, e: 'With config supplied at run time, the artifact that passed tests in staging is byte for byte the artifact that runs in production, so a green test says something about what users will get. Rebuilding per environment breaks that: the production build is one nobody tested. Committing the values back into the repository puts you where you started, and it is how credentials end up in Git - the Twelve-Factor test is whether the codebase could be open-sourced today without leaking any.', intro: 'If the values live inside the artifact, what has to happen before it can run somewhere else?', tags: ['Config', 'separation'] },
  { q: 'Where should a third-party API key used by your server live?', opts: ['In a secret store, injected as an environment variable at run time', 'In a .env file committed to the repo so every environment matches', 'In the client bundle, so the browser can call the API directly', 'In a source file that each developer keeps out of Git locally'], a: 0, e: 'The key belongs in a secret store the platform injects at run time: never in the repository, never in the built bundle, and rotatable without a code change. A committed .env file is readable by everyone with repository access and stays in the history after deletion. A locally ignored file is one mistaken commit or one bad build config away from the same outcome, and anything shipped to the browser is public however it is bundled.', intro: 'Ask which options put the key somewhere it can be read by anyone who obtains the repository or the page.', tags: ['Config', 'secrets'] },
  { q: 'Which difference between staging and production is most likely to let a bug through?', opts: ['Staging runs an older database engine and has no CDN in front', 'Staging runs on smaller instances of the same instance type', 'Staging holds anonymized copies of production records', 'Staging is reachable at a different hostname'], a: 0, e: 'Staging is useful in proportion to how closely its behavior matches production: a different engine version or a missing CDN changes query plans, caching and header handling, so a bug can pass staging and fail in production. Smaller instances, a different hostname and anonymized data change size and content rather than behavior, and are the normal trade-offs. Mirror the shape of the stack; you do not have to mirror its size.', intro: 'For each difference, ask whether code could take a different path because of it.', tags: ['Config', 'staging'] },
  { q: 'The Twelve-Factor App offers a test for whether config is properly separated from code. What is the test?', opts: ['Whether the codebase could be open-sourced today without leaking credentials', 'Whether the app still starts with no environment variables set', 'Whether every environment\'s values are checked in next to the code', 'Whether config changes ship through the same pipeline as code changes'], a: 0, e: 'Twelve-Factor states the test as whether the codebase could be made open source at any moment without compromising any credentials; if it could not, config is still tangled with code. Starting with no environment variables set is not the goal - a service that needs a database URL should refuse to start rather than invent one. Checking each environment\'s values into the repository is precisely the arrangement the test is meant to catch.', intro: 'The test is answered by looking at the repository alone, not at how the app is deployed or started.', tags: ['Config', 'twelve-factor'] },
  { q: 'Why should staging have its own database rather than pointing at production\'s?', opts: ['Test writes and migrations then cannot damage real user data', 'Queries run faster when two environments do not share a pool', 'Staging needs a different schema from the one production runs', 'Production backups only work when a single environment writes'], a: 0, e: 'The point is blast radius: a bad migration, a seeded test user or a truncating fixture in staging touches staging data only. Staging should run the same schema as production - that is what makes it a rehearsal - so a schema difference is a warning sign, not a benefit. Sharing also puts staging\'s load and locks on the production database.', intro: 'Ask what staging does to a database that you would never do to production\'s.', tags: ['Config', 'isolation'] },
  { q: 'Hardcoding environment-specific URLs in the app is problematic because:', opts: ['It is flexible', 'It requires code changes/rebuilds to move between environments', 'It improves config', 'It is required'], a: 1, e: 'Hardcoded URLs couple the build to one environment; externalize them as config instead.', tags: ['Config', 'hardcoding'] },
  { q: 'A service reads DATABASE_URL only when the first request arrives. What does validating it at startup change?', opts: ['A missing value fails the deploy instead of the first user\'s request', 'The value is encrypted while the process is running', 'The service retries the connection until the variable appears', 'The value can then be changed without restarting the process'], a: 0, e: 'Checking required config during startup turns a missing or malformed value into an immediate, named failure: the new instance never reports healthy, so a rolling deploy stops and the previous version keeps serving. Without it the same mistake surfaces later as a stack trace on a user\'s request, whenever that request happens to arrive. Validation does not encrypt anything and does not make values reloadable - it only moves the failure earlier.', intro: 'Validation only reads a value and checks its shape. Ask what that could and could not change.', tags: ['Config', 'validation'] },

  // Level 12 — Observability & Logging
  { q: 'Why is a JSON log line carrying a timestamp, level and request id more useful than a sentence of prose?', opts: ['It can be filtered and grouped by field without parsing free text', 'It takes less disk space than the equivalent prose message', 'It is written synchronously, so no events are lost in a crash', 'It removes the need to choose a level for the event'], a: 0, e: 'Structure makes fields queryable: select one request id, group errors by route, or filter to level=error without regular expressions over prose. JSON is usually larger than the sentence it replaces, so size is not the benefit, and structure says nothing about whether writes are buffered. The level still has to be chosen deliberately - it becomes a field you can filter on.', intro: 'Compare a prose sentence and a JSON line as input to a machine rather than to a person.', tags: ['Observability', 'logging'] },
  { q: 'Your API, worker and gateway each write logs to their own host. What does shipping them to one store change?', opts: ['One query can follow a single request across all three services', 'Each service can stop writing logs to disk during an incident', 'Log volume falls, because duplicate lines are removed centrally', 'The services no longer need to agree on a log format'], a: 0, e: 'A central store lets one query span services, so you can follow a request through the gateway, the API and the worker instead of opening three sessions and matching timestamps by eye. It does not shrink volume, and it makes a shared field format more important, not less - the common schema is what makes the cross-service query possible. Ephemeral hosts are the other reason: when an instance is replaced, anything left on its disk is gone.', intro: 'Each service still writes the same lines. Ask what changes only about where you read them.', tags: ['Observability', 'aggregation'] },
  { q: 'A service logs at debug in development and at info in production. What does the level actually control?', opts: ['Which events are emitted, so noise can be dropped without a code change', 'How long each event is kept before the log store deletes it', 'Whether the event is written to disk or sent over the network', 'The order in which events are written when several arrive at once'], a: 0, e: 'Each call carries a level that is compared against a threshold configured per environment, so one build can be chatty in development and quiet in production with no edit. Retention is a property of the log store rather than the level, though teams often route levels to different retention. During an incident the level is also a filter: show me warn and above.', intro: 'The same build runs in both environments. Ask what differs at run time.', tags: ['Observability', 'levels'] },
  { q: 'Which question is a metric the right tool for, rather than a log search?', opts: ['Has p95 latency on this endpoint risen over the last hour?', 'What payload did the request that failed at 14:02 contain?', 'Which user id triggered the exception in the checkout handler?', 'What was the stack trace of the first error after the deploy?'], a: 0, e: 'Metrics are pre-aggregated numeric series - counters, gauges, histograms - cheap to keep at fine time resolution, so they answer how has this number moved. Anything needing the detail of one event, such as a payload, a user id or a stack trace, is a log or a trace: metrics deliberately discard that detail in exchange for being cheap to store and fast to chart. Choosing the wrong signal is how teams end up paying log prices for dashboard data.', intro: 'For each question, ask what would have to be kept from a single request to answer it.', tags: ['Observability', 'metrics'] },
  { q: 'A request passes through a gateway, two services and a database, and sometimes takes four seconds. What does a distributed trace show that per-service logs do not?', opts: ['How long each hop took and which one the time was spent in', 'How many requests the gateway handled during that minute', 'The exact SQL text of every query the database executed', 'Which build each service instance was running at the time'], a: 0, e: 'A trace is a tree of timed spans linked by a propagated trace id, so it shows where the four seconds went - the gateway, the second service, or the database call - instead of four separate claims of slowness. Request counts are a metric, and query text or build identity comes from other signals. OpenTelemetry\'s default propagator carries the trace id in the W3C traceparent header, which is what lets spans from different services join into one trace.', intro: 'Every service already logs that it was slow. Ask what is missing when you line those logs up.', tags: ['Observability', 'tracing'] },
  { q: 'A gateway generates an id for each incoming request and passes it to every downstream call. What does that make possible?', opts: ['Selecting every log line and span produced for that one request', 'Retrying the request safely, because the id makes writes idempotent', 'Encrypting the request body end to end across service boundaries', 'Ordering log lines correctly when host clocks disagree'], a: 0, e: 'A correlation id is a join key: every log line and span carrying it belongs to the same request, so one search reconstructs the whole path. It is an identifier and nothing more - it encrypts nothing, and it does not make a write idempotent unless the handler explicitly dedupes on it. Clock skew still has to be handled separately; the id says what belongs together, not what happened first.', intro: 'Ask what the id makes possible on its own, before any handler decides to act on it.', tags: ['Observability', 'correlation'] },
  { q: 'Dashboards are all green, yet one tenant reports errors on one endpoint. What does observability add over monitoring here?', opts: ['Asking new questions of stored telemetry without shipping new code', 'Alerting sooner on the thresholds the dashboards already track', 'Storing fewer signals, so the important ones stand out', 'Preferring logs over metrics as the primary signal'], a: 0, e: 'Monitoring watches signals chosen ahead of time; observability is having enough detail - high-cardinality attributes on traces, events and logs - to slice by tenant, endpoint or build after the fact, without deploying new instrumentation. Tightening thresholds cannot help when the failing dimension is on no dashboard. It is about being able to ask the new question, not about collecting less or ranking one signal type above another.', intro: 'Ask what each option requires you to have decided before the failure happened.', tags: ['Observability', 'concept'] },
  { q: 'A handler logs the entire request body while debugging a failing integration. What is the safest change?', opts: ['Log an allowlist of fields, with credentials replaced by a marker', 'Keep the full body but restrict who can read the log store', 'Keep the full body at debug level, since production runs at info', 'Hash the whole body so the values are no longer readable'], a: 0, e: 'Redact where the log is written: emit only the fields you need and replace credentials with a fixed marker, so the secret never enters the pipeline, its backups, or a third-party log vendor. Access control and a debug level are decisions applied after the data is already written, and one changed level or shared dashboard exposes it. Hashing the whole body destroys the debugging value while still copying the payload.', intro: 'Ask what still ends up in the log store, its backups, and any downstream copy.', tags: ['Observability', 'security'] },

  // Level 13 — Monitoring & Alerting
  { q: 'Which job is monitoring responsible for, as distinct from testing and logging?', opts: ['Watching live signals and raising a problem as it happens', 'Proving a change is correct before it is released', 'Recording what happened so it can be reconstructed later', 'Keeping a copy of data so it can be restored'], a: 0, e: 'Monitoring runs against the live system and its job is detection: sample health signals continuously and raise something when they leave the expected range. Tests run before release and say nothing about the state of production, logs record events for later reconstruction, and backups protect data. They complement each other, and monitoring is the only one meant to interrupt a person.', intro: 'Ask what each job is looking at: a change before release, the running system, or stored history.', tags: ['Monitoring', 'basics'] },
  { q: 'Which condition is worth waking someone for at 3 a.m.?', opts: ['Checkout error rate above the SLO threshold for the last ten minutes', 'One instance in an autoscaling group restarted and was replaced', 'CPU on a worker node crossed 80 percent for one minute', 'A nightly batch job finished later than it usually does'], a: 0, e: 'A page should mean a user-visible problem that will not resolve itself and that the responder can do something about; sustained checkout errors against the SLO is exactly that. A replaced instance is the system working as designed, and a one-minute CPU spike is a cause rather than a symptom - alerting on causes produces pages that need no action. Google\'s SRE guidance is that every page should be actionable, and that effort belongs on symptoms rather than causes.', intro: 'Ask what would still be broken ten minutes later if nobody answered.', tags: ['Monitoring', 'alerts'] },
  { q: 'An on-call rotation receives about forty alerts a shift, most needing no action. What is the predictable result?', opts: ['Responders stop reading them, and a real incident is missed', 'Responders get faster at triage, so incidents resolve sooner', 'The alerting system throttles itself once a rate limit is reached', 'The alerts stop firing once someone retunes the thresholds'], a: 0, e: 'When most alerts require no action, ignoring them becomes the rational response - and the one that mattered is ignored along with the rest. That is alert fatigue, and it costs detection time in exactly the incident alerting was built for. Volume does not train responders; it teaches them that alerts are noise, and the fix is deleting or downgrading the ones that are not actionable.', intro: 'Ask what a responder has learned by the thirty-ninth alert that needed nothing.', tags: ['Monitoring', 'fatigue'] },
  { q: 'A reliability report averages the time from an incident starting until service is restored. Which metric is it reporting?', opts: ['MTTR (mean time to recover)', 'MTBF (mean time between failures)', 'p99 request latency', 'Error-budget burn rate'], a: 0, e: 'MTTR averages the time from an incident starting to service being restored, so it measures how quickly a team recovers; the letters are expanded as recover, repair or restore, and the interval in the stem is what fixes the meaning. MTBF measures the gap between incidents - reliability of uptime rather than speed of recovery. p99 latency describes normal request performance, and error-budget burn rate says how fast you are spending the unreliability the SLO allows.', intro: 'MTBF and MTTR both average an interval. Ask where each interval begins and ends.', tags: ['Monitoring', 'mttr'] },
  { q: 'Traffic to a checkout flow is very low overnight. Why add a synthetic check to it?', opts: ['A scripted run exercises the flow even when no real user does', 'It replays last night\'s real user sessions against production', 'It reduces the load the flow places on the database', 'It removes the need to alert on errors from real users'], a: 0, e: 'A synthetic check runs a scripted transaction on a schedule from outside the system, so a broken checkout is caught at 3 a.m. even though nobody tried to buy anything; passive monitoring stays silent until the first real user arrives. It is generated traffic rather than replayed sessions, and it complements real-user monitoring instead of replacing it: synthetics cover the paths you chose, real traffic covers everything else.', intro: 'Ask where the requests come from at 3 a.m. when nobody is shopping.', tags: ['Monitoring', 'synthetic'] },
  { q: 'A production alert fires outside normal working hours. What does a healthy on-call rotation provide?', opts: ['One permanent responder who owns every incident indefinitely', 'A scheduled responder, escalation paths, and shared load', 'An alternative to automated monitoring and runbooks', 'A guarantee that the service will never need recovery work'], a: 1, e: 'A rotation names in advance who answers a page at any hour, defines who is called next when that person cannot, and spreads the burden so nobody carries it permanently. A single permanent owner is a rotation of one: it fails the moment they are unavailable and it burns them out. On-call sits on top of monitoring and runbooks rather than substituting for them, and it does not make recovery work disappear - it makes sure someone is assigned to it.', intro: 'Ask which arrangement still works on the tenth night, and when the usual person is unreachable.', tags: ['Monitoring', 'oncall'] },
  { q: 'An alert fires that the team has seen before. What should its runbook contain?', opts: ['The checks to run, the likely causes, and how to mitigate each', 'The design rationale for the service and its data model', 'The postmortem from the last time this alert fired', 'The list of people allowed to acknowledge the alert'], a: 0, e: 'A runbook is operational: the diagnostic checks in order, what each result implies, and the mitigation for each cause, so a responder who has never touched the service can act. A design document explains why the system is shaped as it is, which is the wrong altitude mid-incident; a postmortem describes one past event; an access list is neither. The runbook should be linked from the alert itself.', intro: 'It is read at 3 a.m. by someone who did not build the service.', tags: ['Monitoring', 'runbook'] },
  { q: 'Which four measurements belong on a service dashboard first?', opts: ['Latency, traffic, errors, and saturation', 'CPU, memory, disk, and network throughput', 'Deploy count, open bugs, test coverage, and build time', 'Uptime percentage, ticket volume, page count, and MTTR'], a: 0, e: 'The four golden signals are latency, traffic, errors and saturation: together they say how slow, how busy, how broken, and how close to its limit a service is. Host metrics such as CPU and memory are causes - useful once you are debugging, but a service can be failing badly with all of them healthy. Delivery and incident statistics belong on a team dashboard, not the one you open during an outage.', intro: 'Ask what each set measures: the requests, the hosts, the team\'s process, or past incidents.', tags: ['Monitoring', 'dashboards'] },

  // Level 14 — Secrets & Security in CI
  { q: 'A GitHub Actions workflow needs a deploy token. Which handling is correct?', opts: ['Store it as a repository secret and read it from the secrets context', 'Commit it to a file in .github that the workflow sources at run time', 'Echo it once at the start of the job so failures are easier to debug', 'Pass it as a plain workflow input so it appears in the run summary'], a: 0, e: 'Secrets belong in the platform\'s encrypted store and are read through the secrets context as an environment variable or an input, so the value reaches the runner without living in the repository. GitHub masks known secret values in logs but warns that automatic redaction is not guaranteed once a value has been transformed, so printing one deliberately defeats it. Anything committed is readable by everyone with repository access and stays in the history after deletion.', intro: 'Ask where each option leaves a copy of the token, and who can read that copy later.', tags: ['Secrets', 'ci'] },
  { q: 'You pushed a commit containing a live API key to a public repository and noticed five minutes later. What must you do?', opts: ['Rotate the key, then clean the history', 'Force-push a rewritten history and keep using the key', 'Delete the repository and recreate it from a clean clone', 'Make the repository private and keep using the key'], a: 0, e: 'Assume the key was captured: public repositories are scraped continuously, and forks, clones, caches and the API can still serve the object after you rewrite history. Rotating invalidates whatever an attacker holds, which is the only step that actually closes the exposure; cleaning history and tightening visibility limit further copies but do nothing about the copies already taken. Deleting the repository does neither for the key itself.', intro: 'Ask what anyone watching public pushes already has, five minutes in.', tags: ['Secrets', 'leak'] },
  { q: 'A team already injects secrets as per-environment variables. What does a secrets manager add?', opts: ['Central storage with per-identity access, an audit trail, and rotation', 'Encryption of the values, which environment variables never provide', 'A guarantee that the application cannot log the value by mistake', 'Automatic removal of secrets already committed to Git history'], a: 0, e: 'A manager adds the operational controls env vars lack: one place to hold a secret, policies for which identity may read it, an audit log of every read, and rotation without redeploying every consumer. It is not a replacement for env vars - the value usually still arrives as one at run time. Nothing in the store stops your own code from logging the value or cleans a secret out of Git history.', intro: 'An environment variable is just a value on a process. Ask what it cannot do for you.', tags: ['Secrets', 'manager'] },
  { q: 'A deploy job uploads build output to one storage bucket. Which credential follows least privilege?', opts: ['A role that can write only to that bucket, assumed for the job\'s duration', 'A long-lived key with write access to every bucket in the account', 'The account the engineers use, so permissions always match theirs', 'An admin key, paired with a policy document describing what the job may touch'], a: 0, e: 'Least privilege means the credential can do the one thing the job needs and exists only while the job runs - a short-lived role scoped to one bucket. Broad or long-lived keys hand an attacker everything the account can reach if a dependency or a pull request runs hostile code. A policy that is written down but not enforced still grants admin: the limit has to live in the credential, not in the document.', intro: 'Ask what a hostile build script could reach with each credential, and for how long.', tags: ['Secrets', 'least-privilege'] },
  { q: 'What does running npm audit in CI actually tell you?', opts: ['Which installed packages match published advisories, and at what severity', 'Whether the code in your own repository contains exploitable bugs', 'Whether a dependency has been modified since its author published it', 'Which dependencies are unused and could safely be removed'], a: 0, e: 'npm audit sends a description of your dependency tree to the registry and receives advisories matching the installed versions, each with a severity - so it finds known, published problems in code you did not write. It does not analyze your own source, verify that a package matches what its author published, or find unused dependencies; those need static analysis, provenance checks and separate tooling. A clean audit means no matching advisory today, not that the tree is safe.', intro: 'The check compares two lists. Ask what is on each of them.', tags: ['Secrets', 'scanning'] },
  { q: 'A CI job runs npm install and sometimes picks up a newer transitive dependency than the lockfile records. Which change makes the install reproducible?', opts: ['Run npm ci, which installs exactly what the lockfile records', 'Delete the lockfile so every install resolves the tree the same way', 'Pin the direct dependencies with caret ranges in package.json', 'Cache node_modules between runs so the tree stops changing'], a: 0, e: 'npm ci installs strictly from package-lock.json, removes any existing node_modules first, and exits with an error if the lockfile and package.json disagree - it never writes to the lock. npm install is allowed to resolve and update the lock, which is where the surprise version comes from. Deleting the lock removes the record entirely, caret ranges are the looseness being pinned against, and a cache hides drift rather than preventing it.', intro: 'Ask what each change does to the lockfile: read it, ignore it, or rewrite it.', tags: ['Secrets', 'supply-chain'] },
  { q: 'A popular npm package publishes a patch release whose install script exfiltrates environment variables. From the point of view of the applications that install it, what kind of attack is this?', opts: ['A supply-chain attack, delivered through a trusted dependency', 'A phishing attack, aimed at the package\'s maintainers', 'A denial-of-service attack, aimed at the package registry', 'A cross-site scripting attack, aimed at the browser'], a: 0, e: 'The compromise reaches every application that installs the package, so the trust relationship in the dependency chain is the attack surface - that is what makes it a supply-chain attack, whatever technique got the attacker publish rights. Phishing a maintainer may be how the account fell, but that is the entry point, not the effect on consumers. Lockfiles, reviewing version bumps, and skipping install scripts in CI all narrow the exposure.', intro: 'The malicious code runs on machines whose owners never chose to run it.', tags: ['Secrets', 'supply-chain'] },
  { q: 'A public repository runs pull-request code in CI. Which setup creates the greatest security risk?', opts: ['Use read-only checkout permissions and no production secrets', 'Give untrusted jobs production secrets and a privileged runner', 'Require maintainers to approve jobs that need protected resources', 'Run untrusted jobs in isolated disposable environments'], a: 1, e: 'A fork\'s pull request can change both the code and, on some triggers, the workflow that runs it, so whatever the job can reach is effectively public: production secrets plus a privileged runner means one pull request exfiltrates them. GitHub does not pass repository secrets to workflows triggered by pull_request from a fork, for exactly this reason, and it advises that self-hosted runners should almost never be used on public repositories. Required approval and disposable isolated runners are the mitigations, not the risk.', intro: 'The code in a pull request was written by someone you have not vetted. Ask what each setup would hand it.', tags: ['Secrets', 'pr-risk'] },

  // Level 15 — Reliability & SRE
  { q: 'What distinguishes an SRE team from a traditional operations team?', opts: ['It treats operations as a software problem and automates the recurring work', 'It owns the product roadmap in addition to the production systems', 'It writes the application code and leaves deploys to the developers', 'It handles incidents instead of setting measurable reliability targets'], a: 0, e: 'SRE applies software engineering to operations: recurring manual work is treated as a defect to be automated, and teams cap the share of time it may consume so engineering time survives. Reliability targets and error budgets are central to the practice rather than an alternative to incident response. It is not a product-ownership role, and SREs do not take over writing the application.', intro: 'Ask whether each option describes who owns what, or how the work itself gets done.', tags: ['SRE', 'basics'] },
  { q: 'A team measures its successful-request ratio, targets 99.9% internally, and promises 99.5% in customer contracts. What are those three things?', opts: ['The measurement is the SLI, the internal target the SLO, the contract the SLA', 'The measurement is the SLO, the internal target the SLI, the contract the SLA', 'The measurement is the SLI, the internal target the SLA, the contract the SLO', 'All three are the same number, published to three different audiences'], a: 0, e: 'The SLI is the measurement - here the ratio of successful requests. The SLO is the internal target you run the service against, and it is deliberately stricter than the SLA, the contractual promise whose breach carries consequences such as credits. Setting the SLO equal to the SLA leaves no margin: you would owe penalties the moment you missed your own target.', intro: 'One of the three is a number you observe; the other two are promises made to different audiences.', tags: ['SRE', 'slo'] },
  { q: 'A service has a 99.9% availability SLO for the quarter. What is its error budget, and what is it for?', opts: ['0.1% of the quarter may be unavailable; spending it slows feature releases', '0.1% of requests may be retried before an incident has to be declared', '99.9% of the quarter must pass before the next release is permitted', '0.1% of the engineering budget is set aside for reliability work'], a: 0, e: 'The error budget is what the SLO leaves over - 100% minus 99.9% is 0.1% of the quarter - and it is the unreliability the team is permitted to spend on risky changes. While budget remains, releases proceed; when it is exhausted, the SRE book\'s policy is to halt releases and put the effort into testing and reliability instead. It is an allowance of downtime, not of retries and not of money.', intro: 'Subtract the target from 100%, then ask who is allowed to spend the difference.', tags: ['SRE', 'error-budget'] },
  { q: 'Which task counts as toil under the SRE definition?', opts: ['Running the same restart script by hand whenever a queue backs up', 'Reviewing a design document for a new storage layer', 'Cleaning up alerting rules so fewer pages are meaningless', 'Attending the weekly incident review meeting'], a: 0, e: 'Toil is manual, repetitive, automatable work tied to running a service that leaves it in the same state afterward and scales with traffic - a hand-run restart script is the textbook case, and it should become automated remediation. The SRE book explicitly excludes administrative overhead such as meetings, and excludes grungy work with lasting value: tidying alerting rules is unglamorous but you do it once. Reviewing a design is engineering work, not toil.', intro: 'Notice which tasks leave something permanently changed and which leave things exactly as they were.', tags: ['SRE', 'toil'] },
  { q: 'A service runs two identical app instances behind a managed load balancer, both reading one database. Where is the single point of failure?', opts: ['The database, since losing it takes the whole service down', 'The load balancer\'s health check interval', 'The app instances, since they run the same image', 'Nowhere: two instances already make the system redundant'], a: 0, e: 'Redundancy only protects the components that have it: two app instances survive losing one, but every request still reaches the same database, so its failure is an outage. Running the same image is not a failure mode - it is what makes the instances interchangeable. Counting instances is not the test; tracing the request path and finding the component with no replacement is.', intro: 'Take one component at a time and ask what its failure would do to a request.', tags: ['SRE', 'redundancy'] },
  { q: 'Which outcome shows that an incident postmortem was useful?', opts: ['It names the person who made the triggering change', 'It records contributing conditions, lessons, and owned follow-ups', 'It avoids documenting the failure to protect the team', 'It schedules a deployment without identifying what should change'], a: 1, e: 'A useful postmortem records what happened and what it cost, the conditions that combined to cause it, and a short list of owned follow-up actions - a written record someone can act on. Naming the person who made the triggering change buys nothing: the blameless principle assumes everyone acted reasonably with the information they had, and it is the system, not the person, that can be fixed. Skipping the write-up to protect the team removes the one artifact that makes the lesson outlast the people who were on call.', intro: 'Ask what the document must contain for the same incident to be less likely next quarter.', tags: ['SRE', 'postmortem'] },
  { q: 'A service already autoscales. Why does it still need capacity planning?', opts: ['Scaling has limits and lead time, and downstream quotas stay fixed', 'Autoscaling only adds instances during business hours', 'Autoscaling cannot remove instances once demand falls', 'Capacity planning replaces autoscaling once traffic is predictable'], a: 0, e: 'Autoscaling reacts, and reacting takes time: instances must boot and warm up, account quotas and connection limits cap how far a group can grow, and the database or third-party API behind the app tier does not scale with it. Planning sets those ceilings deliberately - headroom, quota increases, and load tests against the forecast peak. Autoscaling does shrink when demand falls and does not stop at 6 p.m.; the gap it leaves is the one planning fills.', intro: 'Autoscaling adds instances. Ask what it does not add, and what those instances still depend on.', tags: ['SRE', 'capacity'] },
  { q: 'The overall aim of DevOps/SRE is to deliver software that is:', opts: ['Shipped slowly and breaks often', 'Released frequently and remains reliable, observable, and recoverable', 'Never deployed', 'Untested'], a: 1, e: 'DevOps/SRE combine speed and stability: ship often while keeping systems reliable, observable, and quick to recover.', tags: ['SRE', 'goal'] },
];
